// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount, address caller) public {
        amount = bound(amount, 1, type(uint96).max);
        vm.assume(caller != address(this));
        uint256 expectedLimit = c.currentBetLimit();
        vm.prank(caller);
        try c.AdjustBetAmounts(amount) {
            assertEq(c.currentBetLimit(), expectedLimit);
        } catch {
            assertEq(c.currentBetLimit(), expectedLimit);
        }
    }
}
